# name: lag2_repeat_equal_switch
# description: Among pairs with equal switch counts that differ in the number of 4-flip strictly alternating windows (HTHT/THTH), the rate of choosing the sequence with fewer such windows; observed above null means people see extended alternation as patterned more than the model predicts (model under-penalises local alternation), below means less.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    seqs = pd.unique(pd.concat([a, b]))
    nsw = {s: sum(x != y for x, y in zip(s, s[1:])) for s in seqs}
    alt = {s: sum(s[i:i + 4] in ("HTHT", "THTH") for i in range(max(0, len(s) - 3))) for s in seqs}
    d = (a.map(alt) - b.map(alt)).to_numpy()
    m = (a.map(nsw) == b.map(nsw)).to_numpy() & (d != 0)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()[m]
    return float(np.mean(np.where(d[m] < 0, y, 1 - y)))

# name: head_balance_equal_switch
# description: Among pairs with equal switch counts whose sequences differ in |#H - #T|, the rate of choosing the more balanced sequence; observed above null means people value an even H/T count more than the model's tally-span cue predicts (model under-produces), below means less.
def test_statistic(df):
    a = df["sequence_a"]; b = df["sequence_b"]
    seqs = pd.unique(pd.concat([a, b]))
    nsw = {s: sum(x != y for x, y in zip(s, s[1:])) for s in seqs}
    imb = {s: abs(2 * s.count("H") - len(s)) for s in seqs}
    d = (a.map(imb) - b.map(imb)).to_numpy()
    m = (a.map(nsw) == b.map(nsw)).to_numpy() & (d != 0)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()[m]
    return float(np.mean(np.where(d[m] < 0, y, 1 - y)))

# name: terminal_effect_participant_sd
# description: SD across participants of each person's rate of choosing the sequence with the shorter final run, among pairs with equal switch counts and differing final runs; observed above null means people differ in recency weighting more than the model's shared terminal penalty allows (it under-produces heterogeneity), below means less.
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    def last_run(s):
        k = 1
        while k < len(s) and s[-1 - k] == s[-1]:
            k += 1
        return k
    nsw = {s: sum(x != y for x, y in zip(s, s[1:])) for s in seqs}
    lr = {s: last_run(s) for s in seqs}
    a = df["sequence_a"]; b = df["sequence_b"]
    d = (a.map(lr) - b.map(lr)).to_numpy()
    m = (a.map(nsw) == b.map(nsw)).to_numpy() & (d != 0)
    if m.sum() == 0:
        return 0.0
    y = df["chose_left"].to_numpy()[m]
    ch = np.where(d[m] < 0, y, 1 - y)
    r = pd.Series(ch).groupby(df["participant_id"].to_numpy()[m]).mean()
    return float(r.std(ddof=0))

# name: longest_run_location_equal_longest
# description: Among pairs with equal switch counts and equal longest-run length where exactly one sequence has its longest run touching an edge (first or last flip), the rate of choosing the sequence whose longest run is interior; observed above null means people penalise edge streaks (start or end) more than the model predicts, below means they penalise interior streaks more.
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    def runs(s):
        out, c = [], 1
        for x, y in zip(s, s[1:]):
            if x == y:
                c += 1
            else:
                out.append(c); c = 1
        out.append(c)
        return out
    R = {s: runs(s) for s in seqs}
    nsw = {s: len(r) for s, r in R.items()}
    mx = {s: max(r) for s, r in R.items()}
    edge = {s: float(max(r) in (r[0], r[-1])) for s, r in R.items()}
    a = df["sequence_a"]; b = df["sequence_b"]
    ea = a.map(edge).to_numpy(); eb = b.map(edge).to_numpy()
    m = ((a.map(nsw) == b.map(nsw)) & (a.map(mx) == b.map(mx))).to_numpy() & (ea != eb)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()[m]
    return float(np.mean(np.where(ea[m] < eb[m], y, 1 - y)))

# name: initial_streak_equal_switch
# description: Among pairs with equal numbers of switches and equal final-run length where the first runs differ in length, the rate of choosing the sequence with the shorter opening run; observed above null means people also penalise a sequence that starts on a streak (primacy) which the model, penalising only the terminal run, under-produces; below means the reverse.
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    def first_run(s):
        k = 1
        while k < len(s) and s[k] == s[0]:
            k += 1
        return k
    def last_run(s):
        return first_run(s[::-1])
    nsw = {s: sum(x != y for x, y in zip(s, s[1:])) for s in seqs}
    fr = {s: first_run(s) for s in seqs}
    lr = {s: last_run(s) for s in seqs}
    a = df["sequence_a"]; b = df["sequence_b"]
    d = (a.map(fr) - b.map(fr)).to_numpy()
    m = ((a.map(nsw) == b.map(nsw)) & (a.map(lr) == b.map(lr))).to_numpy() & (d != 0)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()[m]
    return float(np.mean(np.where(d[m] < 0, y, 1 - y)))

# name: run_length_variety_equal_switch_terminal
# description: Among pairs with equal numbers of switches and equal final-run length whose sequences differ in the number of distinct run lengths, the rate of choosing the sequence with more distinct run lengths; observed above null means people prize irregular run lengths more than the model (which has no run-length-variety cue beyond triplets) predicts, below means less.
def test_statistic(df):
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    def runs(s):
        out, c = [], 1
        for x, y in zip(s, s[1:]):
            if x == y:
                c += 1
            else:
                out.append(c); c = 1
        out.append(c)
        return out
    R = {s: runs(s) for s in seqs}
    nsw = {s: len(r) for s, r in R.items()}
    var = {s: len(set(r)) for s, r in R.items()}
    last = {s: r[-1] for s, r in R.items()}
    a = df["sequence_a"]; b = df["sequence_b"]
    dv = a.map(var) - b.map(var)
    m = (a.map(nsw) == b.map(nsw)) & (a.map(last) == b.map(last)) & (dv != 0)
    if m.sum() == 0:
        return 0.5
    y = df["chose_left"].to_numpy()[m.to_numpy()]
    ch = np.where(dv[m].to_numpy() > 0, y, 1 - y)
    return float(np.mean(ch))
